<template><div v-if="member"><button class="back-btn" @click="$emit('back')"><ChevronLeft/>Voltar para equipe</button><div class="welcome-row"><div><p class="eyebrow">ATIVIDADES DO MEMBRO</p><h1>{{member.name}}</h1><p class="subcopy">{{member.job}} · {{member.role}}</p></div></div><section class="panel member-overview"><Avatar :member="member"/><div><strong>{{member.name}}</strong><span>{{member.email}}</span></div><dl><div><dt>Status</dt><dd :class="member.blocked?'blocked-text':'active-text'">{{member.blocked?'Acesso bloqueado':'Ativo'}}</dd></div><div><dt>Tarefas</dt><dd>{{related.length}}</dd></div><div><dt>Projetos</dt><dd>{{relatedProjects}}</dd></div></dl></section><section class="panel"><div class="panel-head"><div><h2>Tarefas atribuídas</h2><p>Atividades no workspace atual</p></div></div><div class="table-wrap"><table><tbody><tr v-for="t in related" :key="t.id" @click="$emit('task',t)"><td><strong>{{t.title}}</strong></td><td>{{projects.find(p=>p.id===t.projectId)?.name}}</td><td>{{t.due}}</td><td><span :class="['status',t.status==='Concluída'?'green':t.status==='Em andamento'?'blue':'gray']">{{t.status}}</span></td></tr></tbody></table></div></section></div><div v-else class="empty">Membro não encontrado.</div></template>
<script setup lang="ts">import{computed}from"vue";import{ChevronLeft}from"lucide-vue-next";import Avatar from"./Avatar.vue";import type{Member,Project,Task}from"../stores/taskflow";const props=defineProps<{member?:Member;tasks:Task[];projects:Project[]}>();defineEmits(["back","task"]);const related=computed(()=>props.tasks.filter(t=>t.assigneeId===props.member?.id)),relatedProjects=computed(()=>new Set(related.value.map(t=>t.projectId)).size);</script>
